package com.greenocean.backend.wellbeing.service;
import com.greenocean.backend.catalog.service.GrowthLibrary;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import java.util.*;

@Service @Transactional
public class LearningCourses {
 private final JdbcTemplate db;private final GrowthLibrary library;private final ObjectMapper json;private final boolean enabled;
 public LearningCourses(JdbcTemplate db,GrowthLibrary library,ObjectMapper json,@Value("${greenocean.education.learning-enabled:false}")boolean enabled){this.db=db;this.library=library;this.json=json;this.enabled=enabled;}
 public record Completion(String contentDigest,boolean acknowledged){}
 public record Check(String contentDigest,int option){}
 public record LearningEvent(UUID owner,String type,UUID completion){}
 @org.springframework.beans.factory.annotation.Autowired org.springframework.context.ApplicationEventPublisher events;
 private void require(UUID actor){library.actor(actor);if(!enabled)throw new com.greenocean.backend.listener.live.LiveSupportException(503,"LEARNING_DISABLED","Structured learning is awaiting its release approval.");}
 private Map<String,Object> source(UUID actor,UUID course){require(actor);var r=library.detail(actor,course);if(!"COURSE".equals(((Map<?,?>)r.get("document")).get("kind")))throw new NotFoundException("Reviewed course was not found");return r;}
 private Map<String,Object> lesson(UUID actor,UUID course,UUID key){var source=source(actor,course);var rows=db.queryForList("SELECT * FROM learning_lessons(?,?) WHERE lesson_key=?",course,source.get("revision"),key);if(rows.isEmpty())throw new NotFoundException("Reviewed lesson was not found");var result=rows.getFirst();if(result.get("exercise")!=null)result.put("exercise",json.readValue(result.get("exercise").toString(),Map.class));result.put("courseRevision",source.get("revision"));return result;}
 public Map<String,Object> browse(UUID actor,String search,String language,int page){require(actor);var result=new LinkedHashMap<>(library.browse(actor,search,"COURSE","",language,false,page));var items=(List<Map<String,Object>>)result.get("items");for(var row:items){UUID id=(UUID)row.get("id");row.put("progress",progress(actor,id));}return result;}
 public Map<String,Object> course(UUID actor,UUID id){var result=new LinkedHashMap<>(source(actor,id));result.put("progress",progress(actor,id));return result;}
 public Map<String,Object> progress(UUID actor,UUID id){var source=source(actor,id);int revision=((Number)source.get("revision")).intValue();var lessons=db.queryForList("SELECT l.lesson_key,l.module_position,l.module_title,l.lesson_position AS position,l.title,l.minutes,l.required,EXISTS(SELECT 1 FROM learning_lesson_completions c WHERE c.owner_id=? AND c.source_course_key=? AND c.lesson_key=l.lesson_key AND c.content_digest=l.content_digest) AS completed FROM learning_lessons(?,?) l ORDER BY l.module_position,l.lesson_position",actor,id,id,revision);long required=lessons.stream().filter(l->Boolean.TRUE.equals(l.get("required"))).count(),done=lessons.stream().filter(l->Boolean.TRUE.equals(l.get("required"))&&Boolean.TRUE.equals(l.get("completed"))).count();return Map.of("revision",revision,"lessons",lessons,"requiredLessons",required,"completedRequiredLessons",done,"percent",required==0?0:(int)(100*done/required),"historicalCompletions",db.queryForObject("SELECT count(*) FROM learning_lesson_completions WHERE owner_id=? AND source_course_key=?",Integer.class,actor,id),"revisionPolicy","Unchanged lesson content preserves completion. New or changed required material needs a new explicit completion; historical records remain private.");}
 public Map<String,Object> open(UUID actor,UUID course,UUID key){var lesson=lesson(actor,course,key);db.update("INSERT INTO learning_lesson_views(owner_id,course_id,lesson_key,revision,content_digest) VALUES (?,?,?,?,?) ON CONFLICT(owner_id,course_id,lesson_key) DO UPDATE SET revision=EXCLUDED.revision,content_digest=EXCLUDED.content_digest,opened_at=CURRENT_TIMESTAMP",actor,course,key,lesson.get("courseRevision"),lesson.get("content_digest"));return lesson;}
 private void currentView(UUID actor,UUID course,UUID key,String digest,Map<String,Object> lesson){if(!Objects.equals(digest,lesson.get("content_digest")))throw new ConflictException("The reviewed lesson changed. Open its current version before completing it.");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_lesson_views WHERE owner_id=? AND course_id=? AND lesson_key=? AND revision=? AND content_digest=?)",Boolean.class,actor,course,key,lesson.get("courseRevision"),digest)))throw new ConflictException("Open the actual reviewed lesson first.");}
 public Map<String,Object> complete(UUID actor,UUID course,UUID key,Completion in){var lesson=lesson(actor,course,key);if(!in.acknowledged())throw new IllegalArgumentException("Explicit reading/activity acknowledgement is required; no private response is needed.");currentView(actor,course,key,in.contentDigest(),lesson);UUID completion=db.queryForObject("INSERT INTO learning_lesson_completions(owner_id,course_id,source_course_key,course_revision,lesson_key,content_digest,lesson_title) VALUES (?,?,?,?,?,?,?) ON CONFLICT(owner_id,source_course_key,lesson_key,content_digest) DO UPDATE SET lesson_title=learning_lesson_completions.lesson_title RETURNING id",UUID.class,actor,course,course,lesson.get("courseRevision"),key,in.contentDigest(),lesson.get("title"));events.publishEvent(new LearningEvent(actor,"LESSON",completion));var progress=progress(actor,course);if(((Number)progress.get("percent")).intValue()==100){var source=source(actor,course);UUID milestone=db.queryForObject("INSERT INTO learning_course_completions(owner_id,course_id,source_course_key,course_revision,course_title) VALUES (?,?,?,?,?) ON CONFLICT(owner_id,source_course_key,course_revision) DO UPDATE SET course_title=learning_course_completions.course_title RETURNING id",UUID.class,actor,course,course,lesson.get("courseRevision"),((Map<?,?>)source.get("document")).get("title"));events.publishEvent(new LearningEvent(actor,"COURSE",milestone));}return Map.of("completionId",completion,"progress",progress);}
 public Map<String,Object> check(UUID actor,UUID course,UUID key,Check in){var lesson=lesson(actor,course,key);currentView(actor,course,key,in.contentDigest(),lesson);if(!(lesson.get("exercise") instanceof Map<?,?> exercise)||!"CHOICE".equals(exercise.get("type")))throw new IllegalArgumentException("This lesson has no optional factual check");var choices=(List<?>)exercise.get("choices");if(in.option()<0||in.option()>=choices.size())throw new IllegalArgumentException("Choose a published option");boolean correct=((Number)exercise.get("correctIndex")).intValue()==in.option();if(correct){String digest=db.queryForObject("SELECT encode(sha256(convert_to((exercise)::text,'UTF8')),'hex') FROM learning_lessons(?,?) WHERE lesson_key=?",String.class,course,lesson.get("courseRevision"),key);UUID completion=db.queryForObject("INSERT INTO learning_exercise_completions(owner_id,course_id,source_course_key,course_revision,lesson_key,content_digest,exercise_digest) VALUES (?,?,?,?,?,?,?) ON CONFLICT(owner_id,source_course_key,lesson_key,exercise_digest) DO UPDATE SET exercise_digest=EXCLUDED.exercise_digest RETURNING id",UUID.class,actor,course,course,lesson.get("courseRevision"),key,in.contentDigest(),digest);events.publishEvent(new LearningEvent(actor,"EXERCISE",completion));}return Map.of("correct",correct,"explanation",exercise.get("explanation"),"scope","An optional learning check, not a psychological assessment. You may try again without a penalty.");}
 public Map<String,Object> history(UUID actor,int page){require(actor);if(page<0||page>100000)throw new IllegalArgumentException("Invalid learning history page");return Map.of("lessons",db.queryForList("SELECT id,source_course_key,course_revision,lesson_key,lesson_title,completed_at FROM learning_lesson_completions WHERE owner_id=? ORDER BY completed_at DESC,id DESC LIMIT 20 OFFSET ?",actor,(long)page*20),"courses",db.queryForList("SELECT id,source_course_key,course_revision,course_title,completed_at FROM learning_course_completions WHERE owner_id=? ORDER BY completed_at DESC,id DESC LIMIT 20 OFFSET ?",actor,(long)page*20));}
}
